INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1632, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'Βαθμός δυσκολίας: 1', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1633, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'Διάρκεια: 0:50', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1634, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'Το συγκεκριμένο μέρος του χορωδιακού ρεπερτορίου καταδεικνύει ότι η χορωδία μπορεί εύκολα να κινείται ανάμεσα σε ύφη και εποχές επιβεβαιώνοντας το δυναμικό χαρακτήρα της, χωρίς να απομακρύνεται και από την μακρόχρονη χορωδιακή παράδοση της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1635, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'This particular part of the choral repertoire demonstrates that the choir can easily move between styles and eras, confirming its dynamic character, without departing from the long-standing choral tradition of Corfu.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1636, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'Dieser Teil des Chorrepertoires zeigt, dass sich der Chor leicht zwischen Höhen und Jahreszeiten bewegen kann, um seinen dynamischen Charakter zu bestätigen, ohne sich von der langen Chortradition Korfus zu entfernen.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1637, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'Cette partie du répertoire choral démontre que le chœur peut facilement se déplacer entre des motifs témporaires et stylistiques confirmant son caractère dynamique, sans s’éloigner, au même temps, de la longue tradition chorale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1638, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.description', 'Questa parte del repertorio corale dimostra che il coro può spostarsi facilmente tra stagioni multipli confermando il suo carattere dinamico, senza allontanarsi dalla lunga tradizione corale di Corfù.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1639, '1142a882-ca52-4105-b977-cfd852a56eb0', 'dc.language.iso', 'el', 'en');
