INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1690, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', 'For chorus SΑΤΒ and piano, with chord symbols.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1691, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', 'Το συγκεκριμένο μέρος του χορωδιακού ρεπερτορίου καταδεικνύει ότι η χορωδία μπορεί εύκολα να κινείται ανάμεσα σε ύφη και εποχές επιβεβαιώνοντας το δυναμικό χαρακτήρα της, χωρίς να απομακρύνεται και από την μακρόχρονη χορωδιακή παράδοση της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1692, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', '', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1693, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', 'This particular part of the choral repertoire demonstrates that the choir can easily move between styles and eras, confirming its dynamic character, without departing from the long-standing choral tradition of Corfu.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1694, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', 'Dieser Teil des Chorrepertoires zeigt, dass sich der Chor leicht zwischen Höhen und Jahreszeiten bewegen kann, um seinen dynamischen Charakter zu bestätigen, ohne sich von der langen Chortradition Korfus zu entfernen.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1695, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', 'Cette partie du répertoire choral démontre que le chœur peut facilement se déplacer entre des motifs temporaires et stylistiques confirmant son caractère dynamique, sans s’éloigner, au même temps, de la longue tradition chorale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1696, '24652b01-7e79-4036-8284-86b80ee8643f', 'dc.description', 'Questa parte del repertorio corale dimostra che il coro può spostarsi facilmente tra stagioni multipli confermando il suo carattere dinamico, senza allontanarsi dalla lunga tradizione corale di Corfù.', 'it');
