INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1784, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Ανάθεση του Κέντρου Χορωδιακής Πράξης', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1785, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Τα τραγούδια προέρχονται από την ταινία "Λόλα"--Σημείωση του καταγραφέα', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1786, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Διάρκεια: 3:30', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1787, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Βαθμός δυσκολίας (Κλίμακα 1-6): 2', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1788, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Το συγκεκριμένο μέρος του χορωδιακού ρεπερτορίου καταδεικνύει ότι η χορωδία μπορεί εύκολα να κινείται ανάμεσα σε ύφη και εποχές επιβεβαιώνοντας το δυναμικό χαρακτήρα της, χωρίς να απομακρύνεται και από την μακρόχρονη χορωδιακή παράδοση της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1789, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'This particular part of the choral repertoire demonstrates that the choir can easily move between styles and eras, confirming its dynamic character, without departing from the long-standing choral tradition of Corfu.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1790, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Dieser Teil des Chorrepertoires zeigt, dass sich der Chor leicht zwischen Höhen und Jahreszeiten bewegen kann, um seinen dynamischen Charakter zu bestätigen, ohne sich von der langen Chortradition Korfus zu entfernen.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1791, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Cette partie du répertoire choral démontre que le chœur peut facilement se déplacer entre des motifs témporaires et stylistiques confirmant son caractère dynamique, sans s’éloigner, au même temps, de la longue tradition chorale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1792, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.description', 'Questa parte del repertorio corale dimostra che il coro può spostarsi facilmente tra stagioni multipli confermando il suo carattere dinamico, senza allontanarsi dalla lunga tradizione corale di Corfù.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1793, '522cbe43-ca5c-4a1d-b85f-7bcfe1125214', 'dc.language.iso', 'el', 'en');
