INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1880, '9b293da5-3ac2-4203-a13c-60a5e3a7046d', 'dc.description', 'Το συγκεκριμένο μέρος του χορωδιακού ρεπερτορίου καταδεικνύει ότι η χορωδία μπορεί εύκολα να κινείται ανάμεσα σε ύφη και εποχές επιβεβαιώνοντας τον δυναμικό χαρακτήρα της, χωρίς να απομακρύνεται και από τη μακρόχρονη χορωδιακή παράδοση της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1881, '9b293da5-3ac2-4203-a13c-60a5e3a7046d', 'dc.description', 'This particular part of the choral repertoire demonstrates that the choir can easily move between styles and eras, confirming its dynamic character, without departing from the long-standing choral tradition of Corfu.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1882, '9b293da5-3ac2-4203-a13c-60a5e3a7046d', 'dc.description', 'Dieser Teil des Chorrepertoires zeigt, dass sich der Chor leicht zwischen Höhen und Jahreszeiten bewegen kann, um seinen dynamischen Charakter zu bestätigen, ohne sich von der langen Chortradition Korfus zu entfernen.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1883, '9b293da5-3ac2-4203-a13c-60a5e3a7046d', 'dc.description', 'Cette partie du répertoire choral démontre que le chœur peut facilement se déplacer entre des motifs temporaires et stylistiques confirmant son caractère dynamique, sans s’éloigner, au même temps, de la longue tradition chorale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1884, '9b293da5-3ac2-4203-a13c-60a5e3a7046d', 'dc.description', 'Questa parte del repertorio corale dimostra che il coro può spostarsi facilmente tra stagioni multipli confermando il suo carattere dinamico, senza allontanarsi dalla lunga tradizione corale di Corfù.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1885, '9b293da5-3ac2-4203-a13c-60a5e3a7046d', 'dc.language.iso', 'el', 'en');
