INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1953, 'b32d7c74-5052-4376-97f8-0364f1837705', 'dc.description', 'Το συγκεκριμένο ποίημα του Σολωμού αποτέλεσε βάση για τη διάφορες μελοποιήσεις. Η εδώ παρουσιαζόμενη προέρχεται από το Αιγαίο.', 'el');
