INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1982, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'Παραδοσιακό Σμύρνης', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1983, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'This particular part of the choral repertoire demonstrates that the choir can easily move between styles and eras, confirming its dynamic character, without departing from the long-standing choral tradition of Corfu.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1984, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'Dieser Teil des Chorrepertoires zeigt, dass sich der Chor leicht zwischen Höhen und Jahreszeiten bewegen kann, um seinen dynamischen Charakter zu bestätigen, ohne sich von der langen Chortradition Korfus zu entfernen.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1985, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'Cette partie du répertoire choral démontre que le chœur peut facilement se déplacer entre des motifs temporaires et stylistiques confirmant son caractère dynamique, sans s’éloigner, au même temps, de la longue tradition chorale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1986, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'Questa parte del repertorio corale dimostra che il coro può spostarsi facilmente tra stagioni multipli confermando il suo carattere dinamico, senza allontanarsi dalla lunga tradizione corale di Corfù.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1987, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'Το συγκεκριμένο μέρος του χορωδιακού ρεπερτορίου καταδεικνύει ότι η χορωδία μπορεί εύκολα να κινείται ανάμεσα σε ύφη και εποχές επιβεβαιώνοντας το δυναμικό χαρακτήρα της, χωρίς να απομακρύνεται και από την μακρόχρονη χορωδιακή παράδοση της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (1988, 'c6d0bb55-a9cf-4c82-b373-8cf622780dc8', 'dc.description', 'Διασκευή για μεικτή χορωδία', 'el');
