INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (2048, 'db14d1db-504b-451c-ac4b-8c96e23d4a18', 'dc.description', 'Dieser Teil des Chorrepertoires zeigt, dass sich der Chor leicht zwischen Höhen und Jahreszeiten bewegen kann, um seinen dynamischen Charakter zu bestätigen, ohne sich von der langen Chortradition Korfus zu entfernen.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (2049, 'db14d1db-504b-451c-ac4b-8c96e23d4a18', 'dc.description', 'Cette partie du répertoire choral démontre que le chœur peut facilement se déplacer entre des motifs temporaires et stylistiques confirmant son caractère dynamique, sans s’éloigner, au même temps, de la longue tradition chorale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (2050, 'db14d1db-504b-451c-ac4b-8c96e23d4a18', 'dc.description', 'Questa parte del repertorio corale dimostra che il coro può spostarsi facilmente tra stagioni multipli confermando il suo carattere dinamico, senza allontanarsi dalla lunga tradizione corale di Corfù.', 'it');
