INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3402, '00d07a81-ad67-4726-a503-1f1c7e360687', 'dc.identifier.uri', 'http://trumpet.di.ionio.gr/xmlui/handle/123456789/681', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3403, '00d07a81-ad67-4726-a503-1f1c7e360687', 'dc.description', 'Η συγκεκριμένη όπερα του Ραχμάνινωφ πρωτοπαρουσιάστηκε στo Κίεβο το 1893. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ Κέρκυρας υπογραμμίζει τις ποικίλες αναφορές που είχε δημιουργήσει η μακρόχρονη επαφή του ακροατηρίου με το μελόδραμα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3404, '00d07a81-ad67-4726-a503-1f1c7e360687', 'dc.description', 'This opera by Rachmaninoff was first performed in Kiev in 1893. The presence of its recording in the archives of the Hellenic Broadcasting Corporation underlines the various references created by the long contact of the audience with melodrama.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3405, '00d07a81-ad67-4726-a503-1f1c7e360687', 'dc.description', 'Rahmaninows besondere Oper wurde erstmals 1893 in Kiew gezeigt. Die Anwesenheit ihrer Aufnahme in den Archiven von ERA Korfu unterstreicht die verschiedenen Referenzen, die durch den langjährigen Kontakt des Publikums mit dem Melodram entstanden sind.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3406, '00d07a81-ad67-4726-a503-1f1c7e360687', 'dc.description', 'L’opéra particulier de Rahmaninov a été présenté pour la première fois à Kiev en 1893. La présence de son enregistrement dans les archives de l’ERA Corfu souligne les diverses références créées par le contact de longue date de l’auditoire avec le mélodrame.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3407, '00d07a81-ad67-4726-a503-1f1c7e360687', 'dc.description', 'La particolare opera di Rahmaninov fu presentata per la prima volta a Kiev nel 1893. La presenza della sua registrazione nell''archivio di ERA Corfu sottolinea i vari riferimenti creati dal lungo contatto del pubblico con il melodramma.', 'it');
