INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3552, '0758660c-ca86-4ba1-85b5-4d3dbbbec9c1', 'dc.description', 'Συμφωνικό έργο του Κερκυραίου ιατρού και συνθέτη Βαγγέλη Πετσάλη (γεν. 1965), ο οποίος συνεχίζει έναν μακρύ δρόμο στην έντεχνη μουσική σύνθεση του νησιού που ξεκινά από τον 16ο αιώνα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3553, '0758660c-ca86-4ba1-85b5-4d3dbbbec9c1', 'dc.description', 'Symphonic work by the Corfiot doctor and composer Vangelis Petsalis (b. 1965), who continues a long path in the island''s art music composition that starts from the 16th century.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3554, '0758660c-ca86-4ba1-85b5-4d3dbbbec9c1', 'dc.description', 'Sinfonisches Werk des korfiotischen Arztes und Komponisten Vangelis Petsalis (gen.1965), die einen langen Weg zur künstlerischen musikalischen Komposition der Insel fortsetzt, die aus dem 16. Jahrhundert beginnt.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3555, '0758660c-ca86-4ba1-85b5-4d3dbbbec9c1', 'dc.description', 'Œuvre symphonique du médecin et compositeur Corfiote Vangelis Petsalis (gen.1965), qui poursuit un long chemin vers la composition musicale artistique de l’île qui part du 16ème siècle.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3556, '0758660c-ca86-4ba1-85b5-4d3dbbbec9c1', 'dc.description', 'Opera sinfonica del medico e compositore di Corfiot Vangelis Petsalis (gen.1965), che continua una lunga strada verso la composizione artistica musicale dell''isola che inizia dal secolo.', 'it');
