INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3722, '11a0e1b8-e600-4369-b131-be6291ad4704', 'dc.description', 'Απόσπασμα από την όπερα του Μότσαρτ “Μιθριδάτης, βασιλεύς του Πόντου”. Η παρουσία ηχογράφησής του στο αρχείο της ΕΡΑ Κέρκυρας υπογραμμίζει τις ποικίλες μουσικές αναφορές των ακροατών του σταθμού.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3723, '11a0e1b8-e600-4369-b131-be6291ad4704', 'dc.description', 'Auszug aus Mozarts Oper Mithridates, König von Pontus. Die Anwesenheit seiner Aufnahme im Archiv von ERA Korfu unterstreicht die verschiedenen musikalischen Berichte der Hörer des Senders.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3724, '11a0e1b8-e600-4369-b131-be6291ad4704', 'dc.description', 'Extrait de l’opéra de Mozart Mithridates, roi de Pontus. La présence de son enregistrement dans les archives de l’ERA Corfu met en lumière les divers reportages musicaux des auditeurs de la station.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (3725, '11a0e1b8-e600-4369-b131-be6291ad4704', 'dc.description', 'Estratto dall''opera di Mozart Mitridates, re del Ponto. La presenza della sua registrazione nell''archivio dell''ERA Corfù mette in evidenza i vari resoconti musicali degli ascoltatori della stazione.', 'it');
