INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4340, '3136cbb2-b105-4ae1-91bd-25b11d4fa831', 'dc.description', 'Μια από τις εμβληματικότερες εκπομπές του ραδιοφωνικού σταθμού της Κέρκυρας, η οποία επί χρόνια υπηρετεί τη συνέχιση της οπερατικής κουλτούρας στο νησί. Επιμέλεια και παρουσίαση από τον ψυχίατρο και συγγραφέα Νάσο Μαρτίνο με την ιδιότητά του ως συνεργάτη της ΕΡΑ Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4341, '3136cbb2-b105-4ae1-91bd-25b11d4fa831', 'dc.description', 'One of the most emblematic broadcasts of the Corfu radio station, which for years has served the continuation of the operatic culture on the island. Edited and presented by the psychiatrist and writer Nasos Martinos in his capacity as an associate of the Hellenic Radio Station in Corfu.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4342, '3136cbb2-b105-4ae1-91bd-25b11d4fa831', 'dc.description', 'Eine der ikonischsten Sendungen des Radiosenders Korfu, der seit Jahren der Fortsetzung der Opernkultur auf der Insel dient.Kuratiert und präsentiert von Psychiater und Schriftsteller Nassos Martinos in seiner Eigenschaft als Mitarbeiter von ERA Corfu.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4343, '3136cbb2-b105-4ae1-91bd-25b11d4fa831', 'dc.description', 'L’une des émissions les plus emblématiques de la station de radio Corfu, qui a servi pendant des années à la poursuite de la culture opératique sur l’île.Présidé et présenté par le psychiatre et écrivain Nassos Martinos en sa qualité d’associé de l’ERA Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4344, '3136cbb2-b105-4ae1-91bd-25b11d4fa831', 'dc.description', 'Una delle trasmissioni più iconiche della stazione radio di Corfù, che per anni ha servito la continuazione della cultura lirica sull''isola.Curato e presentato dallo psichiatra e scrittore Nassos Martinos nella sua veste di socio di ERA Corfù.', 'it');
