INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4631, '39359542-1b26-40a3-a642-47860dbeed43', 'dc.description', 'Χορευτική μουσική, όπως αυτή πέρασε στον χώρο της κερκυραϊκής υπαίθρου. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4632, '39359542-1b26-40a3-a642-47860dbeed43', 'dc.description', 'Dance music, as it passed in the Corfiot countryside. The contribution of the Corfu Radio and Television Association (ERA Corfu) and the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4633, '39359542-1b26-40a3-a642-47860dbeed43', 'dc.description', 'Tanzmusik, wie diese, ging in die Gegend der korfiotischen Landschaft. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4634, '39359542-1b26-40a3-a642-47860dbeed43', 'dc.description', 'La musique de danse, comme celle-ci, est passée à la campagne de Corfiote. La contribution de l’ARN Corfu au sauvetage de ces sons est cruciale.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4635, '39359542-1b26-40a3-a642-47860dbeed43', 'dc.description', 'Musica danzante, come questa passata alla zona della campagna Corfiot. Il contributo dell''ANR di Corfù al salvataggio di questi suoni è fondamentale.', 'it');
