INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4680, '3b15bad2-338d-4cc6-a9f5-5f91381ff0ad', 'dc.description', 'Η ομότιτλη όπερα του Φρανκέτι παρουσιάστηκε στη Γένοβα το 1892. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ Κέρκυρας υπογραμμίζει αφενός τις ευρύτερες αναφορές του μελοδραματικού είδους στην περιοχή και αφετέρου τον βαθμό αποδοχής του ύφους του συγκεκριμένου μουσουργού', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4681, '3b15bad2-338d-4cc6-a9f5-5f91381ff0ad', 'dc.description', 'Franchetti''s opera of the same name was performed in Genoa in 1892. The presence of its recording in the archives of the Hellenic Broadcasting Corporation underlines both the wider references of the melodramatic genre in the region and the degree of acceptance of the style of this particular composer.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4682, '3b15bad2-338d-4cc6-a9f5-5f91381ff0ad', 'dc.description', 'Frankettis gleichnamige Oper wurde 1892 in Genua aufgeführt. Die Anwesenheit der Aufnahme in den Archiven der Korfu NRA unterstreicht einerseits die breiteren Bezüge des melodramatischen Genres in der Region und den Grad der Akzeptanz des Stils des jeweiligen Musikers.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4683, '3b15bad2-338d-4cc6-a9f5-5f91381ff0ad', 'dc.description', 'L’opéra du même nom de Franchetti fut joué à Gênes en 1892. La présence de l’enregistrement dans les archives de la NRA Corfu souligne d’une part les références plus larges du genre mélodramatique dans la région et le degré d’acceptation du style du musicien en particulier.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4684, '3b15bad2-338d-4cc6-a9f5-5f91381ff0ad', 'dc.description', 'L''omonima opera di Franketti fu eseguita a Genova nel 1892. La presenza della registrazione negli archivi della Corfu NRA sottolinea da un lato i riferimenti più ampi del genere melodrammatico nella regione e il grado di accettazione dello stile del particolare musicista.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4685, '3b15bad2-338d-4cc6-a9f5-5f91381ff0ad', 'dc.language.iso', 'el', 'en');
