INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4708, '3bf742ec-0a80-4381-8e48-03fa0e1c8842', 'dc.description', 'Τα κερκυραϊκά κάλαντα των Χριστουγέννων αποδιδόμενα από το φωνητικό σύνολο “Το αργαστήρι”. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4709, '3bf742ec-0a80-4381-8e48-03fa0e1c8842', 'dc.description', 'The Corfiot Christmas carols rendered by the vocal ensemble "To Argastiri". The contribution of the Hellenic Radio Station in Corfu and the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4710, '3bf742ec-0a80-4381-8e48-03fa0e1c8842', 'dc.description', 'Die Corfiot Weihnachtslieder, die vom Vokalensemble  aufgeführt werden. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4711, '3bf742ec-0a80-4381-8e48-03fa0e1c8842', 'dc.description', 'Les carols de Noël Corfiote interprétés par l’ensemble vocal «The Later». La contribution de l’ARN Corfu au sauvetage de ces sons est cruciale.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4712, '3bf742ec-0a80-4381-8e48-03fa0e1c8842', 'dc.description', 'I canti di Natale Corfiot eseguiti dall''ensemble vocale "The Later". Il contributo dell''ANR di Corfù al salvataggio di questi suoni è fondamentale.', 'it');
