INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4831, '4a472326-a014-4c44-bf94-4d20aaa91b0f', 'dc.description', 'Απόσπασμα από την ομότιτλη όπερα του Βέρντι. Ίσως ένα από τα γνωστότερα οπερατικά χορωδιακά σε παγκόσμια κλίμακα, συνεχίζει να είναι ιδιαίτερα δημοφιλές στα κερκυραϊκά συναυλιακά ρεπερτόρια.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4832, '4a472326-a014-4c44-bf94-4d20aaa91b0f', 'dc.description', 'Excerpt from Verdi''s opera of the same name. Perhaps one of the best known operatic choruses on a global scale, it continues to be particularly popular in Corfu concert repertoires.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4833, '4a472326-a014-4c44-bf94-4d20aaa91b0f', 'dc.description', 'Auszug aus Verdis gleichnamiger Oper.Vielleicht ist einer der berühmtesten Opernchöre weltweit nach wie vor besonders beliebt in Corfiot Konzertrepertoires.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4834, '4a472326-a014-4c44-bf94-4d20aaa91b0f', 'dc.description', 'Extrait de l’opéra de Verdi du même nom. Peut-être l’un des plus célèbres choeurs d’opéra à l’échelle mondiale continue-t-il d’être particulièrement populaire dans les répertoires de concerts Corfiote.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4835, '4a472326-a014-4c44-bf94-4d20aaa91b0f', 'dc.description', 'Estratto dall''omonima opera di Verdi. Forse uno dei cori lirici più famosi su scala globale continua ad essere particolarmente popolare nei repertori di concerti di Corfiot.', 'it');
