INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4853, '4c0848ba-bc69-4b8a-8cee-f76ab4636c86', 'dc.identifier.uri', 'http://trumpet.di.ionio.gr/xmlui/handle/123456789/891', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4854, '4c0848ba-bc69-4b8a-8cee-f76ab4636c86', 'dc.description', 'Απόσπασμα από την ομότιτλη όπερα του Βέρντι. Η όπερα του παρουσιάστηκε στην Κέρκυρα το 1855. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ υπογραμμίζει τις ποικίλες συνιστώσες που διαμόρφωσαν σε βάθους χρόνου το μουσικό αισθητήριο της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4855, '4c0848ba-bc69-4b8a-8cee-f76ab4636c86', 'dc.description', 'Excerpt from Verdi''s opera of the same name. His opera was performed in Corfu in 1855. The presence of a recording of it in the Hellenic Broadcasting Corporation''s archive underlines the various components that shaped Corfu''s music sense over time.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4856, '4c0848ba-bc69-4b8a-8cee-f76ab4636c86', 'dc.description', 'Auszug aus Verdis gleichnamiger Oper. Seine Oper wurde 1855 in Korfu aufgeführt. Die Anwesenheit ihrer Aufnahme in der NRA-Datei unterstreicht die verschiedenen Komponenten, die die musikalische Sinneswahrnehmung Korfus tief geprägt haben.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4857, '4c0848ba-bc69-4b8a-8cee-f76ab4636c86', 'dc.description', 'Extrait de l’opéra de Verdi du même nom. Son opéra a été joué à Corfu en 1855. La présence de son enregistrement dans le fichier NRA souligne les divers éléments qui ont profondément façonné la sensorie musicale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4858, '4c0848ba-bc69-4b8a-8cee-f76ab4636c86', 'dc.description', 'Estratto dall''omonima opera di Verdi. La sua opera è stata eseguita a Corfù nel 1855. La presenza della sua registrazione nel file NRA sottolinea le varie componenti che hanno plasmato in profondità il sensore musicale di Corfù.', 'it');
