INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4957, '540778ab-f41b-44be-8ec2-cd0bb5567134', 'dc.description', 'Απόσπασμα από την όπερα “Φλώρα Μιράμπιλις” του Κερκυραίου συνθέτη Σπύρου Σαμάρα. Πρωτοπαρουσιάστηκε στο Μιλάνο το 1886 και στην Κέρκυρα το 1889. Αποτέλεσε τη διαχρονικότερη επιτυχία του.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4958, '540778ab-f41b-44be-8ec2-cd0bb5567134', 'dc.description', 'Excerpt from the opera "Flora Mirabilis" by the Corfiot composer Spyros Samaras. It was first performed in Milan in 1886 and in Corfu in 1889. It was his most enduring success.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4959, '540778ab-f41b-44be-8ec2-cd0bb5567134', 'dc.description', 'Auszug aus der Oper „Flora Mirabilis“ des korfiotischen Komponisten Spyros Samaras. Es wurde erstmals 1886 in Mailand und 1889 in Korfu vorgestellt.Es war sein zeitloser Erfolg.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4960, '540778ab-f41b-44be-8ec2-cd0bb5567134', 'dc.description', 'Extrait de l’opéra «Flora Mirabilis» du compositeur Corfiote Spyros Samaras. Il a été présenté pour la première fois à Milan en 1886 et à Corfu en 1889.C’était son succès intemporel.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (4961, '540778ab-f41b-44be-8ec2-cd0bb5567134', 'dc.description', 'Estratto dall''opera "Flora Mirabilis" del compositore Corfiot Spyros Samaras. Fu presentata per la prima volta a Milano nel 1886 e a Corfù nel 1889.È stato il suo successo maggiore.', 'it');
