INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5058, '55a0f148-82c5-4864-a50d-282bae99d5dd', 'dc.description', 'Χορευτική μουσική, όπως αυτή πέρασε στον χώρο της κερκυραϊκής υπαίθρου. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5059, '55a0f148-82c5-4864-a50d-282bae99d5dd', 'dc.description', 'Dance music, as it passed in the Corfiot countryside. The contribution of the Hellenic Radio Station in Corfu and the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5060, '55a0f148-82c5-4864-a50d-282bae99d5dd', 'dc.description', 'Tanzmusik, wie diese, ging in die Gegend der korfiotischen Landschaft. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5061, '55a0f148-82c5-4864-a50d-282bae99d5dd', 'dc.description', 'La musique de danse, comme celle-ci, est passée à la campagne de Corfiote. La contribution de l’ARN Corfu au sauvetage de ces sons est cruciale.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5062, '55a0f148-82c5-4864-a50d-282bae99d5dd', 'dc.description', 'Musica danzante, come questa passata alla zona della campagna Corfiot. Il contributo dell''ANR di Corfù al salvataggio di questi suoni è fondamentale.', 'it');
