INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5083, '567b6e38-b2f8-4290-b85c-2e230128d491', 'dc.description', 'Τα κερκυραϊκά κάλαντα των Χριστουγέννων αποδιδόμενα από το φωνητικό σύνολο “Το αργαστήρι”. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5084, '567b6e38-b2f8-4290-b85c-2e230128d491', 'dc.description', 'The Corfiot Christmas carols rendered by the vocal ensemble "To Argastiri". The contribution of the Hellenic Radio Station in Corfu and the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5085, '567b6e38-b2f8-4290-b85c-2e230128d491', 'dc.description', 'Die Corfiot Weihnachtslieder, die vom Vokalensemble aufgeführt werden. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
