INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5108, '57cecfe8-a79c-4459-852f-ed505a3f0085', 'dc.description', 'Ορχηστρικό απόσπασμα από την όπερα “Η Μάρτυς” (1894) του Κερκυραίου μουσουργού Σπύρου Σαμάρα, στο οποίο ο συνθέτης βασίζεται στο ρουμανικό μουσικό ύφος, όπως γινόταν κοινώς κατανοητό στα τέλη του 19ου αιώνα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5109, '57cecfe8-a79c-4459-852f-ed505a3f0085', 'dc.description', 'Orchestral excerpt from the opera "The Martyr" (1894) by the Corfiot composer Spyros Samaras, in which the composer based on the Romanian musical style, as it was commonly understood at the end of the 19th century.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5110, '57cecfe8-a79c-4459-852f-ed505a3f0085', 'dc.description', 'Eine instrumentale Passage aus der Oper des korfiotischen Musikers Spiros Samara, auf die sich der Komponist auf den rumänischen Musikstil stützt, wie er im späten 19. Jahrhundert allgemein verstanden wurde.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5111, '57cecfe8-a79c-4459-852f-ed505a3f0085', 'dc.description', 'Un passage instrumental de l’opéra «La Martyre» (1894) du musicien de Corfiote Spiros Samara, sur lequel le compositeur s’appuie sur le style musical roumain, tel qu’il était communément compris à la fin du XIXe siècle.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5112, '57cecfe8-a79c-4459-852f-ed505a3f0085', 'dc.description', 'Un brano strumentale dell''opera "La Martire" (1894) del musicista Corfiot Spiros Samara, su cui il compositore si basa sullo stile musicale rumeno, come è stato comunemente inteso alla fine del secolo.', 'it');
