INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5156, '593bccc9-cc1b-4adc-b959-0eb4c79a0de2', 'dc.identifier.uri', 'http://trumpet.di.ionio.gr/xmlui/handle/123456789/810', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5157, '593bccc9-cc1b-4adc-b959-0eb4c79a0de2', 'dc.description', 'Η παρουσία του συγκεκριμένου έργου του Χίντεμιτ στο αρχείο της ΕΡΑ Κέρκυρας δείχνει ότι η αναζήτηση για ευρύτερες αναφορές στον χώρο της όπερας συνεχίστηκε στην Κέρκυρα και κατά την “εποχή του ραδιοφώνου”.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5158, '593bccc9-cc1b-4adc-b959-0eb4c79a0de2', 'dc.description', 'The presence of this particular work by Hindemith in the archives of the Hellenic Broadcasting Corporation shows that the search for wider references in the opera field continued in Corfu also during the "radio era".', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5159, '593bccc9-cc1b-4adc-b959-0eb4c79a0de2', 'dc.description', 'Die Anwesenheit von Hindemith spezifischer Arbeit in den Archiven der Korfu NRA zeigt, dass die Suche nach weiteren Verweisen auf das Opernhaus in Korfu und während der „Radio-Ära“ fortgesetzt wurde.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5160, '593bccc9-cc1b-4adc-b959-0eb4c79a0de2', 'dc.description', 'La présence de l’œuvre spécifique de Hindemit dans les archives de la NRA de Corfu montre que la recherche de références plus larges à l’opéra s’est poursuivie à Corfu et pendant l’«ère radio».', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5161, '593bccc9-cc1b-4adc-b959-0eb4c79a0de2', 'dc.description', 'La presenza dell''opera specifica di Hindemith negli archivi dell''ANR di Corfù dimostra che la ricerca di maggiori riferimenti al teatro lirico è proseguita a Corfù e durante l''era radio.', 'it');
