INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5181, '5a07331b-35e0-4857-9a1f-48a49c4cf8cf', 'dc.identifier.uri', 'http://trumpet.di.ionio.gr/xmlui/handle/123456789/879', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5182, '5a07331b-35e0-4857-9a1f-48a49c4cf8cf', 'dc.description', 'Η συγκεκριμένη σύνθεση του Κεφαλονίτη μουσουργού και αρχιμουσικού Διονύσιου Λαυράγκα θεωρείται ότι εγκαινίασε και σε δημιουργικό επίπεδο την ανατροφοδότηση για το ζήτημα  της εν Ελλάδι “εθνικής μουσικής” στις αρχές του 20ού αιώνα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5183, '5a07331b-35e0-4857-9a1f-48a49c4cf8cf', 'dc.description', 'This particular composition by the Kefalonian composer and musician Dionysios Lavragas is considered to have initiated, on a creative level, the feedback on the issue of "national music" in Greece at the beginning of the 20th century.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5184, '5a07331b-35e0-4857-9a1f-48a49c4cf8cf', 'dc.description', 'Die spezifische Komposition des Kefaloniten Musikers und Dirigenten Dionysios Lavraga gilt als eingeweiht und kreativ inspiriert das Feedback zum Thema „nationale Musik“ in Griechenland zu Beginn des 20. Jahrhunderts.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5185, '5a07331b-35e0-4857-9a1f-48a49c4cf8cf', 'dc.description', 'La composition spécifique du musicien et chef d’orchestre kéfalonite Dionysios Lavraga est considérée comme ayant inauguré et inspiré de manière créative la rétroaction sur la question de la «musique nationale» en Grèce au début du 20ème siècle.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5186, '5a07331b-35e0-4857-9a1f-48a49c4cf8cf', 'dc.description', 'La composizione specifica del musicista e direttore di Kefalonite Dionysios Lavraga è considerata aver inaugurato e ispirato creativamente il feedback sul tema della "musica nazionale" in Grecia all''inizio del secolo.', 'it');
