INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5262, '5c543724-be43-420e-922f-60c9e23448d5', 'dc.description', 'Λαϊκό τραγούδι της κερκυραϊκής υπαίθρου. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5263, '5c543724-be43-420e-922f-60c9e23448d5', 'dc.description', 'Folk song of the Corfiot countryside. The contribution of the Corfu Radio and Television Association (ERA Corfu) and the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5264, '5c543724-be43-420e-922f-60c9e23448d5', 'dc.description', 'Volkslied der korfiotischen Landschaft. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5265, '5c543724-be43-420e-922f-60c9e23448d5', 'dc.description', 'Chanson folklorique de la campagne de Corfiote. La contribution de l’ARN Corfu au sauvetage de ces sons est cruciale.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5266, '5c543724-be43-420e-922f-60c9e23448d5', 'dc.description', 'Canzone popolare della campagna di Corfú. Il contributo dell''ANR di Corfù al salvataggio di questi suoni è fondamentale.', 'it');
