INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5411, '668c7829-2417-4bf4-a0e5-323f77eb2be0', 'dc.description', 'Η όπερα του Μερκαντάντε παρουσιάστηκε στην Κέρκυρα το 1849. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ υπογραμμίζει τις ποικίλες συνιστώσες που διαμόρφωσαν σε βάθους χρόνου το μουσικό αισθητήριο της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5412, '668c7829-2417-4bf4-a0e5-323f77eb2be0', 'dc.description', 'Mercadante''s opera was presented in Corfu in 1849. The presence of its recording in the archives of the Hellenic Broadcasting Corporation underlines the various components that shaped the music sense of Corfu over time.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5413, '668c7829-2417-4bf4-a0e5-323f77eb2be0', 'dc.description', 'Mercandante Oper wurde 1849 in Korfu präsentiert. Die Anwesenheit ihrer Aufnahme in der NRA-Datei unterstreicht die verschiedenen Komponenten, die die musikalische Sinneswahrnehmung Korfus tief geprägt haben.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5414, '668c7829-2417-4bf4-a0e5-323f77eb2be0', 'dc.description', 'L’opéra de Mercandante est présenté à Corfu en 1849. La présence de son enregistrement dans le fichier NRA souligne les divers éléments qui ont profondément façonné la sensorie musicale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5415, '668c7829-2417-4bf4-a0e5-323f77eb2be0', 'dc.description', 'L''opera di Mercandante è stata presentata a Corfù nel 1849. La presenza della sua registrazione nel file NRA sottolinea le varie componenti che hanno plasmato in profondità il sensore musicale di Corfù.', 'it');
