INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5591, '6f8eaeb8-5b37-4a04-bb2b-5a3cd047d7e7', 'dc.description', 'Απόσπασμα από την όπερα του Μότσαρτ “Μιθριδάτης, βασιλεύς του Πόντου”. Η παρουσία ηχογράφησής του στο αρχείο της ΕΡΑ Κέρκυρας υπογραμμίζει τις ποικίλες μουσικές αναφορές των ακροατών του σταθμού.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5592, '6f8eaeb8-5b37-4a04-bb2b-5a3cd047d7e7', 'dc.description', 'Excerpt from Mozart''s opera "Mithridates, King of Pontus". The presence of his recording in the archives of the Corfu Radio and Television Association underlines the diverse musical references of the station''s listeners.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5593, '6f8eaeb8-5b37-4a04-bb2b-5a3cd047d7e7', 'dc.description', 'Auszug aus Mozarts Oper Mithridates, König von Pontus. Die Anwesenheit seiner Aufnahme im Archiv von ERA Korfu unterstreicht die verschiedenen musikalischen Berichte der Hörer des Senders.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5594, '6f8eaeb8-5b37-4a04-bb2b-5a3cd047d7e7', 'dc.description', 'Extrait de l’opéra de Mozart Mithridates, roi de Pontus. La présence de son enregistrement dans les archives de l’ERA Corfu met en lumière les divers reportages musicaux des auditeurs de la station.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (5595, '6f8eaeb8-5b37-4a04-bb2b-5a3cd047d7e7', 'dc.description', 'Estratto dall''opera di Mozart Mitridates, re del Ponto. La presenza della sua registrazione nell''archivio dell''ERA Corfù mette in evidenza i vari resoconti musicali degli ascoltatori della stazione.', 'it');
