INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6128, '87c882e1-30b1-4d4a-b947-f980d8da7863', 'dc.description', 'Χορευτική μουσική της κερκυραϊκής υπαίθρου, βασιζόμενη σε δημοφιλές αυστριακό τραγούδι του τέλους του 19ου αιώνα. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6129, '87c882e1-30b1-4d4a-b947-f980d8da7863', 'dc.description', 'Dance music of the Corfiot countryside, based on a popular Austrian song of the late 19th century. The contribution of the Hellenic Radio Station in Corfu and the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6130, '87c882e1-30b1-4d4a-b947-f980d8da7863', 'dc.description', 'Tanzmusik der korfiotischen Landschaft, basierend auf einem beliebten österreichischen Lied aus dem späten 19. Jahrhundert. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6131, '87c882e1-30b1-4d4a-b947-f980d8da7863', 'dc.description', 'Musique de danse de la campagne Corfiote, basée sur une chanson autrichienne populaire de la fin du 19ème siècle. La contribution de l’ARN Corfu au sauvetage de ces sons est cruciale.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6132, '87c882e1-30b1-4d4a-b947-f980d8da7863', 'dc.description', 'Musica danzante della campagna Corfiot, basata su una popolare canzone austriaca della fine del secolo. Il contributo dell''ANR di Corfù al salvataggio di questi suoni è fondamentale.', 'it');
