INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6177, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.identifier.uri', 'http://trumpet.di.ionio.gr/xmlui/handle/123456789/769', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6178, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.description', 'Το πλέον γνωστό σήμερα σε παγκόσμια κλίμακα έργο του Σαμάρα. Δημιουργήθηκε με αφορμή του πρώτους σύγχρονους Ολυμπιακούς Αγώνες (Αθήνα, 1896), αλλά καθιερώθηκε ως επίσημος ύμνος των εκάστοτε ολυμπιακών εκδηλώσεων το 1958.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6179, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.description', 'The most famous work by Samaras today on a global scale. It was composed on the occasion of the first modern Olympic Games (Athens, 1896), but it was established in 1958 as the official anthem of each Olympic event .', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6180, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.description', 'Samaras bekanntestes Werk heute. Es wurde anlässlich der ersten modernen Olympischen Spiele (Athen, 1896), aber es wurde als offizielle Hymne jedes Olympischen Ereignisses im Jahr 1958 gegründet.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6181, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.description', 'Le travail le plus connu de Samara aujourd’hui. Il a été créé à l’occasion des premiers Jeux olympiques modernes (Athènes, 1896), mais il a été établi comme l’hymne officiel de chaque événement olympique en 1958.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6182, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.description', 'Il lavoro più conosciuto di Samaras oggi. È stato creato in occasione dei primi Giochi Olimpici moderni (Atene, 1896), ma è stato istituito come inno ufficiale di ogni evento olimpico nel 1958.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6183, '8a499e4f-987c-463a-9ab2-44138bb0437e', 'dc.language.iso', 'el', 'en');
