INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6208, '8b59a290-b4ed-4e35-b705-6ccac6b57731', 'dc.description', 'Από τους “36 Ελληνικούς Χορούς” για ορχήστρα (Σειρά 3: “Μεσολογγίτικος Χορός” και “Μαζωχτός”), έργο που συνέβαλε καθοριστικά στην υστεροφημία του Σκαλκώτα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6209, '8b59a290-b4ed-4e35-b705-6ccac6b57731', 'dc.description', 'From the "36 Greek Dances" for orchestra (Series 3: "Mesolongitikos Dance" and "Mazoktos"), a work that contributed decisively to Skalkotas'' fame.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6210, '8b59a290-b4ed-4e35-b705-6ccac6b57731', 'dc.description', 'Aus den „36 griechischen Tänzen“ für Orchester (Serie 3:„Mesologgitiko Dance“ und „Mazokhtos“, ein Werk, das entscheidend zu Skalkotas spätem Ruhm beigetragen hat.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6211, '8b59a290-b4ed-4e35-b705-6ccac6b57731', 'dc.description', 'Tiré des «36 Danses grecques» pour orchestre (Série 3:«Mesologgitiko Dance» et «Mazokhtos», une œuvre qui a contribué de manière décisive à la renommée tardive de Skalkotas.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6212, '8b59a290-b4ed-4e35-b705-6ccac6b57731', 'dc.description', 'Dalle "36 Danze Greche" per orchestra (serie 3: "Danza Mesologgitika" e "Mazokhtos", un''opera che contribuì decisamente alla fama di Skalkotas.', 'it');
