INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6259, '8c27dc41-1bfa-45eb-9572-ee246625c049', 'dc.description', 'Το συγκεκριμένο έργο του Σούμπερτ συντέθηκε το 1816 και κατέστη ένα από τα πλέον αναγνωρίσιμα έργα του, έχοντας πολλές μοτσάρτειες αναφορές.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6260, '8c27dc41-1bfa-45eb-9572-ee246625c049', 'dc.description', 'This particular work by Schubert was composed in 1816 and became one of his most recognizable works, with many mozzartian references.', 'en');
