INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6312, '8dddb471-11e0-476f-ba5e-13a618dabd81', 'dc.description', 'Χορευτική σύνθεση βασισμένη σε προκλασικές αναφορές (Γκαβότα) του Κερκυραίου μουσουργού Ναπολέοντος Λαμπελέτ, ο οποίος μετά την αποχώρησή του από την Ελλάδα διέγραψε μια ενδιαφέρουσα πορεία στο λονδρέζικο μουσικό θέατρο.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6313, '8dddb471-11e0-476f-ba5e-13a618dabd81', 'dc.description', 'Dance composition based on preclassical references (Gavota) by the Corfiot composer Napoleon Labellet, who after leaving Greece had an interesting career in the London musical theatre.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6314, '8dddb471-11e0-476f-ba5e-13a618dabd81', 'dc.description', 'Tanzkomposition nach vorklassischen Referenzen  des korfiotischen Musikers Napoleon Labelette, der nach seinem Verlassen Griechenlands einen interessanten Kurs im Londoner Musiktheater löschte.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6315, '8dddb471-11e0-476f-ba5e-13a618dabd81', 'dc.description', 'Composition de danse basée sur des références préclassiques (Gavota) du musicien de Corfiote Napoléon Labelette, qui après avoir quitté la Grèce a supprimé un cours intéressant dans le théâtre musical de Londres.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6316, '8dddb471-11e0-476f-ba5e-13a618dabd81', 'dc.description', 'Composizione di danza basata su riferimenti preclassici (Gavota) del musicista Corfiot Napoleon Lambelet, che dopo aver lasciato la Grecia ha cancellato un interessante corso nel teatro musicale di Londra.', 'it');
