INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6468, '946c12cd-2bdb-4e1e-8a08-1dac9d44099e', 'dc.description', 'Χορευτική μουσική της κερκυραϊκής υπαίθρου από το ερευνητικό αρχείο της Ακαδημίας Αθηνών. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
