INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6492, '973e203d-0407-44e7-807f-5a29381f4df4', 'dc.description', 'Απόσπασμα από την ομότιτλη όπερα του Ωμπέρ. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ υπογραμμίζει τις ποικίλες συνιστώσες που διαμόρφωσαν σε βάθους χρόνου το μουσικό αισθητήριο της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6493, '973e203d-0407-44e7-807f-5a29381f4df4', 'dc.description', 'Excerpt from Auber''s opera of the same name. The presence of a recording of this opera in the archives of the Hellenic Broadcasting Corporation underlines the various components that have shaped the music sense of Corfu over time.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6494, '973e203d-0407-44e7-807f-5a29381f4df4', 'dc.description', 'Auszug aus Auberts gleichnamiger Oper. Die Anwesenheit ihrer Aufnahme in der NRA-Datei unterstreicht die verschiedenen Komponenten, die die musikalische Sinneswahrnehmung Korfus tief geprägt haben.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6495, '973e203d-0407-44e7-807f-5a29381f4df4', 'dc.description', 'Extrait de l’opéra d’Aubert du même nom. La présence de son enregistrement dans le fichier NRA souligne les divers éléments qui ont profondément façonné la sensorie musicale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6496, '973e203d-0407-44e7-807f-5a29381f4df4', 'dc.description', 'Estratto dall''omonima opera di Auber. La presenza della sua registrazione nel file NRA sottolinea le varie componenti che hanno plasmato in profondità il sensore musicale di Corfù.', 'it');
