INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6517, '97d4e1e3-d59f-4198-a29f-00f950556041', 'dc.description', 'Χορευτική μουσική της κερκυραϊκής υπαίθρου, βασιζόμενη σε δημοφιλές αυστριακό τραγούδι του τέλους του 19ου αιώνα. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
