INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6618, '9b3dbc1e-97a2-4ab2-ad77-09943d05a012', 'dc.description', 'Απόσπασμα από την χαρακτηριστικότερη ορχηστρική σύνθεση του Κεφαλονίτη συνθέτη και μαέστρου Διονύσιου Λαυράγκα, δια της οποίας διερμηνεύει το αίτημα της αναζήτησης “εθνικού χαρακτήρα” στην έντεχνη μουσική της Ελλάδας των αρχών του 20ού αιώνα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6619, '9b3dbc1e-97a2-4ab2-ad77-09943d05a012', 'dc.description', 'Excerpt from the most characteristic orchestral composition of the Cephalonian composer and conductor Dionysios Lavragas, through which he interprets the demand of the search for "national character" in the art music of Greece at the beginning of the 20th century.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6620, '9b3dbc1e-97a2-4ab2-ad77-09943d05a012', 'dc.description', 'Ein Auszug aus der charakteristischsten Orchesterkomposition des Komponisten und Dirigenten Dionysios Lavragas, durch die er die Bitte um die Suche nach einem „nationalen Charakter“ in der griechischen Musik des frühen 20. Jahrhunderts interpretiert.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6621, '9b3dbc1e-97a2-4ab2-ad77-09943d05a012', 'dc.description', 'Extrait de la composition orchestrale la plus caractéristique du compositeur et chef d’orchestre Dionysios Lavraga, par laquelle il interprète la demande de recherche d’un «caractère national» dans la musique artistique grecque du début du 20ème siècle.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6622, '9b3dbc1e-97a2-4ab2-ad77-09943d05a012', 'dc.description', 'Un estratto dalla composizione orchestrale più caratteristica del compositore e direttore d''orchestra Dionysios Lavragas, attraverso il quale interpreta la richiesta di ricerca di un "carattere nazionale" nella musica d''arte della Grecia dell''inizio del secolo.', 'it');
