INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6767, 'a1ef6324-7542-4e34-b508-c136e1c36d0e', 'dc.description', 'Απόσπασμα από την ομότιτλη όπερα του Βέρντι. Η όπερα του παρουσιάστηκε στην Κέρκυρα το 1849. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ υπογραμμίζει τις ποικίλες συνιστώσες που διαμόρφωσαν σε βάθους χρόνου το μουσικό αισθητήριο της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6768, 'a1ef6324-7542-4e34-b508-c136e1c36d0e', 'dc.description', 'Excerpt from Verdi''s opera of the same name. His opera was performed in Corfu in 1849. The presence of a recording of it in the Hellenic Broadcasting Corporation''s archive underlines the various components that shaped Corfu''s music sense over time.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6769, 'a1ef6324-7542-4e34-b508-c136e1c36d0e', 'dc.description', 'Auszug aus Verdis gleichnamiger Oper. Seine Oper wurde 1849 in Korfu aufgeführt. Die Anwesenheit ihrer Aufnahme in der NRA-Datei unterstreicht die verschiedenen Komponenten, die die musikalische Sinneswahrnehmung Korfus tief geprägt haben.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6770, 'a1ef6324-7542-4e34-b508-c136e1c36d0e', 'dc.description', 'Extrait de l’opéra de Verdi du même nom. Son opéra a été joué à Corfu en 1849. La présence de son enregistrement dans le fichier NRA souligne les divers éléments qui ont profondément façonné la sensorie musicale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6771, 'a1ef6324-7542-4e34-b508-c136e1c36d0e', 'dc.description', 'Estratto dall''omonima opera di Verdi. La sua opera è stata eseguita a Corfù nel 1849. La presenza della sua registrazione nel file NRA sottolinea le varie componenti che hanno plasmato in profondità il sensore musicale di Corfù.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6772, 'a1ef6324-7542-4e34-b508-c136e1c36d0e', 'dc.language.iso', 'el', 'en');
