INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6949, 'aeb8aa3a-db62-44f1-bf8a-946d2a01f2c5', 'dc.description', 'Η όπερα παρουσιάστηκε στην Κέρκυρα το 1898. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ υπογραμμίζει τις ποικίλες συνιστώσες που διαμόρφωσαν σε βάθους χρόνου το μουσικό αισθητήριο της Κέρκυρας.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6950, 'aeb8aa3a-db62-44f1-bf8a-946d2a01f2c5', 'dc.description', 'The opera was presented in Corfu in 1898. The presence of its recording in the archives of the Hellenic Broadcasting Corporation underlines the various components that shaped the music sense of Corfu over time.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6951, 'aeb8aa3a-db62-44f1-bf8a-946d2a01f2c5', 'dc.description', 'Die Oper wurde 1898 in Korfu aufgeführt. Die Anwesenheit ihrer Aufnahme in der NRA-Datei unterstreicht die verschiedenen Komponenten, die die musikalische Sinneswahrnehmung Korfus tief geprägt haben.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6952, 'aeb8aa3a-db62-44f1-bf8a-946d2a01f2c5', 'dc.description', 'L’opéra a été joué à Corfu en 1898. La présence de son enregistrement dans le fichier NRA souligne les divers éléments qui ont profondément façonné la sensorie musicale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6953, 'aeb8aa3a-db62-44f1-bf8a-946d2a01f2c5', 'dc.description', 'L''opera è stata eseguita a Corfù nel 1898. La presenza della sua registrazione nel file NRA sottolinea le varie componenti che hanno plasmato in profondità il sensore musicale di Corfù.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (6954, 'aeb8aa3a-db62-44f1-bf8a-946d2a01f2c5', 'dc.language.iso', 'el', 'en');
