INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7104, 'b24ac28c-58af-4eb4-95ac-e1cba5f20cea', 'dc.description', 'Χορευτική μουσική της κερκυραϊκής υπαίθρου με σαφείς αναφορές στα ακούσματα της πόλης. Η συμβολή της ΕΡΑ Κέρκυρας και στη διάσωση των ακουσμάτων αυτών είναι κομβική.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7105, 'b24ac28c-58af-4eb4-95ac-e1cba5f20cea', 'dc.description', 'Dance music of the Corfiot countryside with clear references to the sounds of the city. The contribution of the Corfu Radio and Television Association to the preservation of these sounds is crucial.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7106, 'b24ac28c-58af-4eb4-95ac-e1cba5f20cea', 'dc.description', 'Tanzmusik der korfiotischen Landschaft mit klaren Verweisen auf die Klänge der Stadt. Entscheidend ist der Beitrag der Korfu NRA zur Rettung dieser Geräusche.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7107, 'b24ac28c-58af-4eb4-95ac-e1cba5f20cea', 'dc.description', 'Musique de danse de la campagne Corfiote avec des références claires aux sons de la ville. La contribution de l’ARN Corfu au sauvetage de ces sons est cruciale.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7108, 'b24ac28c-58af-4eb4-95ac-e1cba5f20cea', 'dc.description', 'Musica danzante della campagna Corfiot con chiari riferimenti ai suoni della città. Il contributo dell''ANR di Corfù al salvataggio di questi suoni è fondamentale.', 'it');
