INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7128, 'b2f312f7-ddef-4fb2-b8e6-ab96307862fb', 'dc.description', 'Χορευτική σύνθεση βασισμένη σε προκλασικές αναφορές (Μενουέτο) του Κερκυραίου μουσουργού Ναπολέοντος Λαμπελέτ, ο οποίος μετά την αποχώρησή του από την Ελλάδα διέγραψε μια ενδιαφέρουσα πορεία στο λονδρέζικο μουσικό θέατρο.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7129, 'b2f312f7-ddef-4fb2-b8e6-ab96307862fb', 'dc.description', 'Eine Tanzkomposition nach vorklassischen Referenzen (Menuet) des korfioten Musikers Napoleon Labelette, der nach seinem Verlassen Griechenlands einen interessanten Kurs im Londoner Musiktheater löschte.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7130, 'b2f312f7-ddef-4fb2-b8e6-ab96307862fb', 'dc.description', 'Une composition de danse basée sur des références préclassiques (Menuet) du musicien de Corfiote Napoléon Labelet, qui après avoir quitté la Grèce a supprimé un cours intéressant dans le théâtre musical de Londres.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7131, 'b2f312f7-ddef-4fb2-b8e6-ab96307862fb', 'dc.description', 'Una composizione di danza basata su riferimenti preclassici (Menuet) del musicista Corfiot Napoleon Labelette, che dopo aver lasciato la Grecia ha cancellato un interessante corso nel teatro musicale di Londra.', 'it');
