INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7176, 'b767077a-f46b-4086-b443-1d9926341af2', 'dc.description', 'Απόσπασμα από την όπερα του Μότσαρτ “Μιθριδάτης, βασιλεύς του Πόντου”. Η παρουσία ηχογράφησής του στο αρχείο της ΕΡΑ Κέρκυρας υπογραμμίζει τις ποικίλες μουσικές αναφορές των ακροατών του σταθμού.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7177, 'b767077a-f46b-4086-b443-1d9926341af2', 'dc.description', 'Excerpt from Mozart''s opera "Mithridates, King of Pontus". The presence of its recording in the Hellenic Broadcasting Corporation''s archive underlines the diverse musical references of the station''s listeners.', 'en');
