INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7437, 'c277a37a-f079-411d-9ca4-b05f504874f3', 'dc.description', 'Auszug aus Verdis gleichnamiger Oper. Seine Oper wurde 1853 in Korfu aufgeführt. Die Anwesenheit ihrer Aufnahme in der NRA-Datei unterstreicht die verschiedenen Komponenten, die die musikalische Sinneswahrnehmung Korfus tief geprägt haben.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7438, 'c277a37a-f079-411d-9ca4-b05f504874f3', 'dc.description', 'Extrait de l’opéra de Verdi du même nom. Son opéra a été joué à Corfu en 1853. La présence de son enregistrement dans le fichier NRA souligne les divers éléments qui ont profondément façonné la sensorie musicale de Corfu.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7439, 'c277a37a-f079-411d-9ca4-b05f504874f3', 'dc.description', 'Estratto dall''omonima opera di Verdi. La sua opera è stata eseguita a Corfù nel 1853. La presenza della sua registrazione nel file NRA sottolinea le varie componenti che hanno plasmato in profondità il sensore musicale di Corfù.', 'it');
