INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7489, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.description', 'Φιλαρμονική Μάντζαρος', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7490, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.description', 'Ο συγκεκριμένος χόρος ήταν ένα από τα δύο ballabile της διαχρονικής επιτυχίας (πρεμιέρα: Μιλάνο, 1886) του Κερκυραίου μουσουργού Σπύρου Σαμάρα. Σύντομα βρήκε διέξοδο και στα μπαντιστικά ρεπερτόρια της Κέρκυρας, όπου συνεχίζει να ακούγεται μέχρι σήμερα.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7491, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.description', 'This particular dance was one of the two ballabile of the timeless success (premiere: Milan, 1886) of the Corfiot composer Spyros Samaras. Soon it found its way into the band repertoires of Corfu, where it continues to be heard until today.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7492, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.description', 'Dieser Tanz war einer der beiden Ballabile des zeitlosen Erfolgs (Premiere:Mailand, 1886) des korfiotischen Musikers Spyros Samaras. Bald fand er einen Ausweg in den Bandistenrepertoires von Korfu, wo es bis heute zu hören ist.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7493, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.description', 'Cette danse particulière était l’une des deux Ballabile du succès intemporel (premiere:Milan, 1886) par le musicien Corfiote Spyros Samaras. Il a rapidement trouvé une sortie dans les répertoires bandistes de Corfu, où il continue d’être entendu jusqu’à aujourd’hui.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7494, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.description', 'Questa particolare danza è stata una delle due Ballabile di successo senza tempo (premiere:Milano, 1886) del musicista Corfiot Spyros Samaras. Ha trovato presto una via d''uscita nel repertorio bandista di Corfù, dove continua ad essere ascoltato fino ad oggi.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7495, 'c5ff2b9d-e3c4-450d-b97b-439315b15b18', 'dc.language.iso', 'el', 'en');
