INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7615, 'ccc960d2-f24a-49da-9ad2-4af2365bc1b9', 'dc.description', 'Δημοφιλής χορός της κερκυραϊκής υπαίθρου, ο οποίος έλκει ονομασία και μελωδικά στοιχεία από τον βενετσιάνικο χορό friulana (δηλ. Ο προερχόμενος από την περιοχή του Friuli).', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7616, 'ccc960d2-f24a-49da-9ad2-4af2365bc1b9', 'dc.description', 'A popular dance of the Corfiot countryside, which takes its name and melodic elements from the Venetian dance friulana (i.e. coming from the region of Friuli).', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7617, 'ccc960d2-f24a-49da-9ad2-4af2365bc1b9', 'dc.description', 'Beliebter Tanz der korfiotischen Landschaft, der einen Namen und melodische Elemente aus dem venezianischen Friulana-Tanz anzieht (d. h. der aus der Region Friaul).', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7618, 'ccc960d2-f24a-49da-9ad2-4af2365bc1b9', 'dc.description', 'Danse populaire de la campagne de Corfiote, qui attire un nom et des éléments mélodiques de la danse de friulana vénitien (c’est-à-dire celle qui vient de la région du Frioul).', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7619, 'ccc960d2-f24a-49da-9ad2-4af2365bc1b9', 'dc.description', 'Danza popolare della campagna Corfiot, che richiama un nome ed elementi melodici dalla danza friulana veneziana (cioè quella friulana).', 'it');
