INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7691, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.identifier.uri', 'http://trumpet.di.ionio.gr/xmlui/handle/123456789/895', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7692, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.description', 'Η ομότιτλη όπερα του Φρανκέτι παρουσιάστηκε στη Γένοβα το 1892. Η παρουσία ηχογράφησής της στο αρχείο της ΕΡΑ Κέρκυρας υπογραμμίζει αφενός τις ευρύτερες αναφορές του μελοδραματικού είδους στην περιοχή και αφετέρου τον βαθμό αποδοχής του ύφους του συγκεκριμένου μουσουργού', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7693, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.description', 'Franchetti''s opera of the same name was performed in Genoa in 1892. The presence of its recording in the archives of the Hellenic Broadcasting Corporation underlines both the wider references of the melodramatic genre in the region and the degree of acceptance of the style of this particular composer.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7694, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.description', 'Frankettis gleichnamige Oper wurde 1892 in Genua aufgeführt. Die Anwesenheit der Aufnahme in den Archiven der Korfu NRA unterstreicht einerseits die breiteren Bezüge des melodramatischen Genres in der Region und den Grad der Akzeptanz des Stils des jeweiligen Musikers.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7695, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.description', 'L’opéra du même nom de Franchetti fut joué à Gênes en 1892. La présence de l’enregistrement dans les archives de la NRA Corfu souligne d’une part les références plus larges du genre mélodramatique dans la région et le degré d’acceptation du style du musicien en particulier.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7696, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.description', 'L''omonima opera di Franketti fu eseguita a Genova nel 1892. La presenza della registrazione negli archivi della Corfu NRA sottolinea da un lato i riferimenti più ampi del genere melodrammatico nella regione e il grado di accettazione dello stile del particolare musicista.', 'it');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7697, 'cf2aae3d-c6c7-4a0d-910b-01e35ced2224', 'dc.language.iso', 'el', 'en');
