INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7717, 'cf60c4df-40dd-44c2-9eea-d2d4afb78010', 'dc.description', 'Απόσπασμα (μουσική μπαλέτου) από την όπερα “Φλώρα Μιράμπιλις” του Κερκυραίου συνθέτη Σπύρου Σαμάρα. Πρωτοπαρουσιάστηκε στο Μιλάνο το 1886 και στην Κέρκυρα το 1889. Αποτέλεσε τη διαχρονικότερη επιτυχία του.', 'el');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7718, 'cf60c4df-40dd-44c2-9eea-d2d4afb78010', 'dc.description', 'Excerpt (ballet music) from the opera "Flora Mirabilis" by the Corfiot composer Spyros Samaras. It was first performed in Milan in 1886 and in Corfu in 1889. It was his most enduring success.', 'en');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7719, 'cf60c4df-40dd-44c2-9eea-d2d4afb78010', 'dc.description', 'Auszug aus der Oper „Flora Mirabilis“ des korfiotischen Komponisten Spyros Samaras. Es wurde erstmals 1886 in Mailand und 1889 in Korfu vorgestellt.Es war sein zeitloser Erfolg.', 'de');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7720, 'cf60c4df-40dd-44c2-9eea-d2d4afb78010', 'dc.description', 'Extrait de l’opéra «Flora Mirabilis» du compositeur Corfiote Spyros Samaras. Il a été présenté pour la première fois à Milan en 1886 et à Corfu en 1889.C’était son succès intemporel.', 'fr');
INSERT INTO `MetadataValues` (`Id`, `ItemId`, `Field`, `Value`, `Language`) VALUES (7721, 'cf60c4df-40dd-44c2-9eea-d2d4afb78010', 'dc.description', 'Estratto dell''opera "Flora Mirabilis" del compositore Corfiot Spyros Samaras. Fu presentata per la prima volta a Milano nel 1886 e a Corfù nel 1889.È stato il suo successo maggiore.', 'it');
